    87	fn write_ppm(
    88	    out: &mut impl Write,
    89	    width: usize,
    90	    height: usize,
    91	    pixels: &[Colour],
    92	) -> io::Result<()> {
    93	    writeln!(out, "P3\n{width} {height}\n255")?;
    94	    for pixel in pixels {
    95	        writeln!(
    96	            out,
    97	            "{} {} {}",
    98	            to_byte(pixel.x),
    99	            to_byte(pixel.y),
   100	            to_byte(pixel.z)
   101	        )?;
   102	    }
   103	    Ok(())
   104	}
