   106	/// Resolve the command line into the settings one render uses.
   107	fn parse_args(args: &[String]) -> Result<Settings, String> {
   108	    let mut width = DEFAULT_WIDTH;
   109	    let mut height = DEFAULT_HEIGHT;
   110	    let mut samples = DEFAULT_SAMPLES;
   111	    let mut output = PathBuf::from(DEFAULT_OUTPUT);
   112	    let mut explicit_format: Option<Format> = None;
   113	
   114	    let mut index = 0;
   115	    while index < args.len() {
   116	        let option = args[index].as_str();
   117	        let value = args.get(index + 1);
   118	        match (option, value) {
   119	            ("--width", Some(value)) => width = parse_number(option, value, 2)?,
   120	            ("--height", Some(value)) => height = parse_number(option, value, 2)?,
   121	            ("--samples", Some(value)) => samples = parse_number(option, value, 1)?,
   122	            ("--output", Some(value)) => output = PathBuf::from(value),
   123	            ("--format", Some(value)) => {
   124	                explicit_format = Some(match value.as_str() {
   125	                    "png" => Format::Png,
   126	                    "ppm" => Format::Ppm,
   127	                    _ => return Err(format!("unknown format {value}")),
   128	                });
   129	            }
   130	            ("--width" | "--height" | "--samples" | "--output" | "--format", None) => {
   131	                return Err(format!("{option} needs a value"));
   132	            }
   133	            _ => return Err(format!("unknown option {option}")),
   134	        }
   135	        index += 2;
   136	    }
   137	
   138	    let format = resolve_format(explicit_format, &output)?;
   139	    Ok(Settings {
   140	        width,
   141	        height,
   142	        samples,
   143	        output,
   144	        format,
   145	    })
   146	}
   147	
   148	/// Parse an option's value as a count of at least `minimum`.
   149	fn parse_number(option: &str, value: &str, minimum: usize) -> Result<usize, String> {
   150	    let number = value
   151	        .parse::<usize>()
   152	        .map_err(|_| format!("{option} needs a number, not {value}"))?;
   153	    if number < minimum {
   154	        return Err(format!("{option} needs at least {minimum}, not {value}"));
   155	    }
   156	    Ok(number)
   157	}
   158	
   159	/// Choose the format: an explicit `--format` wins, otherwise the output extension decides.
   160	fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
   161	    if let Some(format) = explicit {
   162	        return Ok(format);
   163	    }
   164	    match output.extension().and_then(|extension| extension.to_str()) {
   165	        Some("png") => Ok(Format::Png),
   166	        Some("ppm") => Ok(Format::Ppm),
   167	        _ => Err(format!("cannot choose a format for {}", output.display())),
   168	    }
   169	}
   170	
   171	fn run(settings: &Settings) -> io::Result<()> {
   172	    let pixels = render(settings.width, settings.height, settings.samples);
   173	    let mut bytes = Vec::new();
   174	    match settings.format {
   175	        Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
   176	        Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
   177	    }
   178	    fs::write(&settings.output, bytes)
   179	}
   180	
   181	fn main() {
   182	    let args: Vec<String> = std::env::args().skip(1).collect();
   183	    let settings = match parse_args(&args) {
   184	        Ok(settings) => settings,
   185	        Err(message) => {
   186	            eprintln!("error: {message}");
   187	            eprintln!("{USAGE}");
   188	            std::process::exit(2);
   189	        }
   190	    };
   191	    if let Err(error) = run(&settings) {
   192	        eprintln!("error: {error}");
   193	        std::process::exit(1);
   194	    }
   195	}
